// ============================================================
// PROJECT MAPPING: Telegram Chat ID → ClickUp Folder
// Fill in your actual chat IDs and folder IDs below.
// How to find folder IDs: see SETUP.md step 3.
// ============================================================
const PROJECT_MAPPING = {
  "-1001234567890": { name: "Skylife",        folderId: "FOLDER_ID_SKYLIFE" },
  "-1009876543210": { name: "Insight",        folderId: "FOLDER_ID_INSIGHT" },
  "-1001111111111": { name: "Homeland",       folderId: "FOLDER_ID_HOMELAND" },
  "-1002222222222": { name: "Skyparadise",    folderId: "FOLDER_ID_SKYPARADISE" },
  "-1003333333333": { name: "LiveElite",      folderId: "FOLDER_ID_LIVEELITE" },
  "-1004444444444": { name: "The Hub",        folderId: "FOLDER_ID_THEHUB" },
  "-1005555555555": { name: "Ghelichkhani",   folderId: "FOLDER_ID_GHELICHKHANI" },
  "-1006666666666": { name: "Shafiee",        folderId: "FOLDER_ID_SHAFIEE" },
  "-1007777777777": { name: "Qattali",        folderId: "FOLDER_ID_QATTALI" },
  "-1008888888888": { name: "Dorna",          folderId: "FOLDER_ID_DORNA" },
  "-1009999999999": { name: "Arta Group",     folderId: "FOLDER_ID_ARTAROUP" },
  "-1000000000001": { name: "Caribbeanparadise", folderId: "FOLDER_ID_CARIBBEANPARADISE" },
};

const item = items[0].json;
const project = PROJECT_MAPPING[item.chatId];

if (!project) {
  return [{ json: { ...item, projectFound: false } }];
}

return [{ json: { ...item, projectFound: true, projectName: project.name, folderId: project.folderId } }];

const upstream = $('Lookup Project').item.json;
const claudeResponse = items[0].json;

// Extract text content from Claude API response
let rawText = '';
try {
  rawText = claudeResponse.content[0].text;
} catch (e) {
  throw new Error('Claude API returned unexpected structure: ' + JSON.stringify(claudeResponse));
}

// Strip any accidental markdown code fences
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  throw new Error('Claude returned non-JSON: ' + rawText);
}

// Validate required fields
if (typeof parsed.is_task !== 'boolean') {
  throw new Error('Claude response missing is_task field');
}

return [{
  json: {
    // Pass through upstream context
    chatId: upstream.chatId,
    messageId: upstream.messageId,
    messageText: upstream.messageText,
    senderName: upstream.senderName,
    senderId: upstream.senderId,
    projectName: upstream.projectName,
    folderId: upstream.folderId,
    timestamp: upstream.timestamp,
    // AI extraction results
    is_task: parsed.is_task,
    assignee_persian: parsed.assignee_persian || null,
    assignee_english: parsed.assignee_english || null,
    title: parsed.title || null,
    description: parsed.description || null,
    priority: parsed.priority || 'normal',
    due_date: parsed.due_date || null,
  }
}];

// ============================================================
// Fuzzy name matching using Levenshtein distance
// ============================================================
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = [];
  for (let i = 0; i <= m; i++) {
    dp[i] = [i];
    for (let j = 1; j <= n; j++) {
      dp[i][j] = i === 0 ? j : 0;
    }
  }
  for (let j = 1; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
      }
    }
  }
  return dp[m][n];
}

function similarity(a, b) {
  a = a.toLowerCase().trim();
  b = b.toLowerCase().trim();
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1.0;
  return 1 - levenshtein(a, b) / maxLen;
}

const upstream = $('Parse Claude Response').item.json;
const targetName = (upstream.assignee_english || '').toLowerCase().trim();

if (!targetName) {
  return [{ json: { ...upstream, userFound: false, matchReason: 'No assignee name extracted' } }];
}

const teamData = items[0].json;
// ClickUp API returns { teams: [{ id, name, members: [...] }] }
// "teams" here means workspaces — the top-level org, not sub-groups.
const members = (teamData.teams?.[0]?.members) || [];

if (members.length === 0) {
  throw new Error('ClickUp returned empty members list. Verify your API token has workspace access.');
}

let bestMatch = null;
let bestScore = 0;
let bestField = '';

for (const member of members) {
  const user = member.user || {};
  const username = String(user.username || '');
  const email = String(user.email || '').split('@')[0];
  // Some ClickUp workspaces store full name in username; split it
  const nameParts = username.split(/[\s._-]+/);

  const candidates = [username, email, ...nameParts].filter(Boolean);

  for (const candidate of candidates) {
    const score = similarity(targetName, candidate);
    if (score > bestScore) {
      bestScore = score;
      bestMatch = user;
      bestField = candidate;
    }
  }
}

const CONFIDENCE_THRESHOLD = 0.70;

if (bestScore >= CONFIDENCE_THRESHOLD && bestMatch) {
  return [{
    json: {
      ...upstream,
      userFound: true,
      clickupUserId: bestMatch.id,
      clickupUserName: bestMatch.username,
      matchScore: Math.round(bestScore * 100) / 100,
      matchedField: bestField,
    }
  }];
} else {
  return [{
    json: {
      ...upstream,
      userFound: false,
      bestGuess: bestMatch?.username || 'none',
      matchScore: Math.round(bestScore * 100) / 100,
      matchReason: `Best match '${bestField}' scored ${Math.round(bestScore * 100)}% (threshold 70%)`,
    }
  }];
}

// ============================================================
// Find the sprint list whose date range includes today.
// Falls back to: latest sprint → backlog → first list.
// Sprint name format: "Sprint N (M/D - M/D)" e.g. "Sprint 3 (5/3 - 5/9)"
// ============================================================
const upstream = $('Match ClickUp User').item.json;
const listsData = items[0].json;
const lists = listsData.lists || [];

const today = new Date();
today.setHours(12, 0, 0, 0); // midday to avoid TZ edge cases
const currentYear = today.getFullYear();

function parseSprintDates(name) {
  // Matches: Sprint N (M/D - M/D) or Sprint N (M/D - M/D/YYYY)
  const re = /Sprint\s+\d+\s*\((\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?\s*-\s*(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?\)/i;
  const m = name.match(re);
  if (!m) return null;

  const startYear = m[3] ? parseInt(m[3]) : currentYear;
  const endYear   = m[6] ? parseInt(m[6]) : currentYear;

  const start = new Date(startYear, parseInt(m[1]) - 1, parseInt(m[2]));
  const end   = new Date(endYear,   parseInt(m[4]) - 1, parseInt(m[5]), 23, 59, 59);
  return { start, end };
}

let currentSprint = null;
let latestSprint  = null;
let latestStart   = null;
let backlogList   = null;

for (const list of lists) {
  const name = (list.name || '').trim();

  if (/^backlog$/i.test(name)) {
    backlogList = list;
    continue;
  }

  const dates = parseSprintDates(name);
  if (!dates) continue;

  // Is today within this sprint?
  if (today >= dates.start && today <= dates.end) {
    currentSprint = list;
    break;
  }

  // Track latest sprint as fallback
  if (!latestStart || dates.start > latestStart) {
    latestStart  = dates.start;
    latestSprint = list;
  }
}

const targetList = currentSprint || latestSprint || backlogList || lists[0];

if (!targetList) {
  throw new Error(`No lists found in ClickUp folder '${upstream.folderId}' for project '${upstream.projectName}'.`);
}

const usedFallback = !currentSprint;
const fallbackReason = !currentSprint
  ? (latestSprint ? 'No active sprint; using latest sprint' : 'No sprint found; using backlog')
  : null;

return [{
  json: {
    ...upstream,
    listId: targetList.id,
    listName: targetList.name,
    usedFallback,
    fallbackReason,
  }
}];

